import { useState, useEffect, useRef } from "react";

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;500;600;700;800;900&display=swap');
*{margin:0;padding:0;box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{font-family:'Montserrat',sans-serif;color:#1E1E24;overflow-x:hidden;background:#fff;}
::-webkit-scrollbar{width:5px;}
::-webkit-scrollbar-track{background:#F7F7FA;}
::-webkit-scrollbar-thumb{background:linear-gradient(#ED1E79,#662D91);border-radius:3px;}
@keyframes float1{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-22px) rotate(4deg)}}
@keyframes float2{0%,100%{transform:translateY(0)}50%{transform:translateY(-14px)}}
@keyframes float3{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-10px) scale(1.05)}}
@keyframes marquee{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}
@keyframes fadeIn{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:none}}
a{text-decoration:none;color:inherit;}
button{outline:none;font-family:'Montserrat',sans-serif;}
textarea,input,select{font-family:'Montserrat',sans-serif;}
@media(max-width:900px){
  .desk-nav{display:none!important;}
  .mob-tog{display:block!important;}
  .grid-2col{grid-template-columns:1fr!important;}
  .svc-grid{grid-template-columns:1fr!important;}
  .shift-grid{grid-template-columns:1fr!important;gap:40px!important;}
  .stats-row{grid-template-columns:repeat(2,1fr)!important;}
}
@media(max-width:600px){
  .pkg-grid{grid-template-columns:1fr!important;}
  .stats-row{grid-template-columns:1fr!important;}
}
`;

