/* ─── FADE UP ─────────────────────────────────────── */
const FU=({children,d=0,style={}})=>{
  const r=useRef(null);const[v,sv]=useState(false);
  useEffect(()=>{
    const o=new IntersectionObserver(([e])=>{if(e.isIntersecting)sv(true);},{threshold:0.07});
    if(r.current)o.observe(r.current);return()=>o.disconnect();
  },[]);
  return <div ref={r} style={{opacity:v?1:0,transform:v?'none':'translateY(28px)',transition:`opacity .65s ${d}s ease,transform .65s ${d}s ease`,...style}}>{children}</div>;
};

