/* ─── NAV ─────────────────────────────────────── */
const Nav=({page,go})=>{
  const[sc,setSc]=useState(false);const[mo,setMo]=useState(false);
  useEffect(()=>{const h=()=>setSc(window.scrollY>20);window.addEventListener('scroll',h);return()=>window.removeEventListener('scroll',h);},[]);
  const links=['Services','Work','Process','Packages','About','Blog','Contact'];
  return(
    <nav style={{position:'fixed',top:0,left:0,right:0,zIndex:1000,background:'rgba(255,255,255,.97)',backdropFilter:'blur(20px)',borderBottom:sc?'1px solid rgba(102,45,145,.1)':'1px solid transparent',transition:'all .3s',padding:'0 24px'}}>
      <div style={{maxWidth:1200,margin:'0 auto',display:'flex',alignItems:'center',justifyContent:'space-between',height:70}}>
        <button onClick={()=>go('Home')} style={{background:'none',border:'none',cursor:'pointer',padding:0}}><LogoColor h={38}/></button>
        <div className="desk-nav" style={{display:'flex',alignItems:'center',gap:2}}>
          {links.map(l=><button key={l} onClick={()=>go(l)} style={{background:'none',border:'none',cursor:'pointer',padding:'8px 11px',fontSize:13,fontWeight:page===l?700:500,color:page===l?PK:DK,borderBottom:page===l?`2px solid ${PK}`:'2px solid transparent',transition:'color .2s'}}>{l}</button>)}
          <button onClick={()=>window.open('https://calendly.com/forgefusionstudios/15min','_blank')} style={{marginLeft:14,background:GR,color:'#fff',padding:'10px 22px',borderRadius:50,border:'none',cursor:'pointer',fontSize:13,fontWeight:700,whiteSpace:'nowrap'}}>Book a Free Call</button>
        </div>
        <button className="mob-tog" onClick={()=>setMo(!mo)} style={{display:'none',background:'none',border:'none',cursor:'pointer',padding:8}}>
          {[0,1,2].map(i=><div key={i} style={{width:24,height:2,background:PU,marginBottom:i<2?5:0}}/>)}
        </button>
      </div>
      {mo&&(
        <div style={{background:'#fff',padding:'12px 24px 24px',borderTop:'1px solid #F4F0FA'}}>
          {['Home',...links].map(l=><button key={l} onClick={()=>{go(l);setMo(false);}} style={{display:'block',width:'100%',textAlign:'left',background:'none',border:'none',borderBottom:'1px solid #F7F7FA',padding:'12px 0',cursor:'pointer',fontSize:14,fontWeight:page===l?700:500,color:page===l?PK:DK}}>{l}</button>)}
          <button onClick={()=>{window.open('https://calendly.com/forgefusionstudios/15min','_blank');setMo(false);}} style={{marginTop:16,display:'block',width:'100%',background:GR,color:'#fff',padding:14,borderRadius:50,border:'none',cursor:'pointer',fontSize:14,fontWeight:700}}>Book a Free Call</button>
        </div>
      )}
    </nav>
  );
};

