/* ─── ABOUT PAGE ─────────────────────────────────── */
const AboutPage=({go})=>{
  const vals=['Creativity','Collaboration','Excellence','Integrity','Client-Centric','Innovation','Empowerment','Adaptability','Passion','Community'];
  return(
    <div style={{paddingTop:70}}>
      <Hero eyebrow="About Us" title="Igniting creativity. Now powered by smarter systems." sub="A founder-led creative growth studio helping businesses combine creativity, strategy, AI workflows, and digital execution."/>
      <section style={{padding:'80px 24px',background:'#fff'}}>
        <div style={{maxWidth:1100,margin:'0 auto'}}>
          <div className="grid-2col" style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:64,alignItems:'center',marginBottom:80}}>
            <FU>
              <SH eye="Our Story" title="Built on creativity. Upgraded for growth."/>
              <p style={{fontSize:15,color:MD,lineHeight:1.88,marginBottom:16}}>Forge Fusion Studios was built on the belief that creativity can help brands make a meaningful impact. Over the years, the studio has worked across branding, digital marketing, social media, websites, campaigns, and visual storytelling.</p>
              <p style={{fontSize:15,color:MD,lineHeight:1.88,marginBottom:16}}>Today, the studio is evolving. As AI changes how businesses create, market, and grow, Forge Fusion Studios is shifting from traditional creative services toward AI-powered growth systems.</p>
              <p style={{fontSize:15,color:MD,lineHeight:1.88}}>The studio remains rooted in creativity and strategy. AI-assisted workflows now help make the process faster, sharper, and more measurable — without losing human taste and judgment.</p>
            </FU>
            <FU d={.18}>
              <div style={{background:`linear-gradient(135deg,${PK}10,${PU}10)`,borderRadius:24,padding:'44px',textAlign:'center',border:`1px solid ${PK}20`}}>
                <div style={{display:'flex',justifyContent:'center',marginBottom:20}}><IB name="anvil" size={32} padding={20} radius={20}/></div>
                <h3 style={{fontSize:22,fontWeight:800,color:DK,marginBottom:12}}>Founder-Led Advantage</h3>
                <p style={{fontSize:14,color:MD,lineHeight:1.82}}>Clients work directly with Mustafa — the founder, creative director, and strategist — from first call to final delivery. AI-assisted workflows reduce agency bloat while maintaining quality and creative direction.</p>
              </div>
            </FU>
          </div>
          <div className="grid-2col" style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:24,marginBottom:64}}>
            {[
              {t:'Mission',ic:'target',   d:'To bring creativity to life through compelling narratives, captivating designs, and smarter growth systems that help businesses thrive in the digital age.'},
              {t:'Vision', ic:'telescope',d:'To be a beacon of creativity and innovation, setting new standards for design, digital marketing, branding, and AI-powered business growth.'},
            ].map(mv=>(
              <FU key={mv.t}>
                <div style={{background:SF,borderRadius:20,padding:'32px',borderTop:`3px solid ${PK}`,height:'100%'}}>
                  <div style={{marginBottom:14}}><IB name={mv.ic} size={22} padding={12} radius={10}/></div>
                  <h3 style={{fontSize:20,fontWeight:700,color:DK,marginBottom:10}}>{mv.t}</h3>
                  <p style={{fontSize:14,color:MD,lineHeight:1.8}}>{mv.d}</p>
                </div>
              </FU>
            ))}
          </div>
          <FU>
            <h3 style={{fontSize:22,fontWeight:800,color:DK,marginBottom:24,textAlign:'center'}}>Our Values</h3>
            <div style={{display:'flex',flexWrap:'wrap',gap:12,justifyContent:'center'}}>
              {vals.map((v,i)=><span key={v} style={{background:i%2===0?`${PK}15`:`${PU}15`,color:i%2===0?PK:PU,fontSize:13,padding:'10px 20px',borderRadius:50,fontWeight:600,border:`1px solid ${i%2===0?PK:PU}30`}}>{v}</span>)}
            </div>
          </FU>
        </div>
      </section>
      <section style={{padding:'80px 24px',background:GR,textAlign:'center'}}>
        <FU>
          <h2 style={{fontSize:'clamp(26px,4vw,44px)',color:'#fff',fontWeight:900,marginBottom:16}}>Let's forge your growth system.</h2>
          <p style={{fontSize:17,color:'rgba(255,255,255,.85)',marginBottom:36}}>Tell us what you are building and where you want to grow.</p>
          <GBtn white onClick={()=>go('Contact')}>Get in Touch</GBtn>
        </FU>
      </section>
    </div>
  );
};

/* ─── BLOG PAGE ─────────────────────────────────── */
const BlogPage=()=>{
  const cats=['All','AI for Business','Lead Generation','Branding','Website Strategy','Content Marketing','Healthcare Marketing','Founder-Led Growth'];
  const[sel,setSel]=useState('All');
  const posts=[
    {t:"Why Businesses Don't Need More Posts — They Need a Lead Generation System",     cat:'Lead Generation',     min:'5 min',d:"Most businesses believe that posting more on social media will generate leads. The reality is very different.",ic:'target'},
    {t:"How AI Can Help Service Businesses Capture and Follow Up With Leads",           cat:'AI for Business',     min:'6 min',d:"AI-assisted workflows are changing how service businesses manage their leads. A practical breakdown of what's possible today.",ic:'robot'},
    {t:"How Medical Billing Companies Can Use Digital Marketing to Reach More Clinics", cat:'Healthcare Marketing',min:'7 min',d:"Medical billing companies face a unique challenge: selling a complex service to busy healthcare providers.",ic:'medical'},
    {t:"Why Your Website Looks Good But Still Doesn't Generate Leads",                 cat:'Website Strategy',    min:'5 min',d:"Design is only half the equation. A website needs clear messaging, a strong CTA, and a lead capture flow to actually work.",ic:'laptop'},
    {t:"How Founder-Led Agencies Can Compete in the AI Era",                            cat:'Founder-Led Growth',  min:'4 min',d:"The rise of AI tools has actually created a massive advantage for lean, founder-led agencies.",ic:'rocket'},
    {t:"The Difference Between Content Creation and Content Systems",                   cat:'Content Marketing',   min:'5 min',d:"Creating content and building a content system are two very different things. Here's why the system matters more.",ic:'content'},
    {t:"How to Build a Simple Lead Follow-Up System Without Expensive Software",        cat:'Lead Generation',     min:'6 min',d:"You don't need a $500/month CRM to follow up with leads effectively. Here is a simple, low-cost approach.",ic:'clipboard'},
    {t:"Why AI Will Not Replace Creative Direction",                                    cat:'AI for Business',     min:'4 min',d:"AI is changing creative work. But the one thing it cannot replace is human judgment, taste, and strategic thinking.",ic:'brush'},
    {t:"How to Turn a Company Profile into a Lead Generation Asset",                    cat:'Branding',            min:'5 min',d:"Most company profiles are boring PDFs that nobody reads. Here is how to turn yours into an actual sales tool.",ic:'sparkle'},
    {t:"The Future of Branding in an AI-Powered Business World",                       cat:'Branding',            min:'7 min',d:"AI is changing brand building. The brands that will win combine AI speed with human authenticity.",ic:'crystal'},
  ];
  const filtered=sel==='All'?posts:posts.filter(p=>p.cat===sel);
  return(
    <div style={{paddingTop:70}}>
      <Hero eyebrow="Blog" title="Ideas on AI, creativity, branding, and growth." sub="Practical insights for businesses that want better websites, content, lead generation, and creative systems."/>
      <div style={{padding:'20px 24px',background:SF,borderBottom:'1px solid rgba(102,45,145,.08)',overflowX:'auto'}}>
        <div style={{display:'flex',gap:8,maxWidth:1200,margin:'0 auto',flexWrap:'wrap'}}>
          {cats.map(c=><button key={c} onClick={()=>setSel(c)} style={{background:sel===c?GR:'#fff',color:sel===c?'#fff':MD,padding:'8px 16px',borderRadius:50,border:`1px solid ${sel===c?'transparent':'rgba(102,45,145,.15)'}`,cursor:'pointer',fontSize:12,fontWeight:600,whiteSpace:'nowrap',transition:'all .2s'}}>{c}</button>)}
        </div>
      </div>
      <section style={{padding:'64px 24px',background:'#fff'}}>
        <div style={{maxWidth:1200,margin:'0 auto',display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(300px,1fr))',gap:26}}>
          {filtered.map((p,i)=>(
            <FU key={i} d={i*.05}>
              <div style={{background:SF,borderRadius:20,overflow:'hidden',cursor:'pointer',transition:'transform .3s',height:'100%',display:'flex',flexDirection:'column'}}
                onMouseEnter={e=>e.currentTarget.style.transform='translateY(-5px)'}
                onMouseLeave={e=>e.currentTarget.style.transform='none'}>
                <div style={{height:140,background:`linear-gradient(135deg,${PK}18,${PU}18)`,display:'flex',alignItems:'center',justifyContent:'center'}}>
                  <div style={{width:58,height:58,borderRadius:'50%',background:GR,display:'flex',alignItems:'center',justifyContent:'center'}}>
                    <IC name={p.ic} size={26} color="#fff"/>
                  </div>
                </div>
                <div style={{padding:'22px 24px',flex:1,display:'flex',flexDirection:'column'}}>
                  <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:10}}>
                    <span style={{background:`${PK}15`,color:PK,fontSize:11,padding:'4px 10px',borderRadius:50,fontWeight:600}}>{p.cat}</span>
                    <span style={{fontSize:11,color:MD}}>{p.min} read</span>
                  </div>
                  <h3 style={{fontSize:16,fontWeight:700,color:DK,marginBottom:8,lineHeight:1.45,flex:1}}>{p.t}</h3>
                  <p style={{fontSize:13,color:MD,lineHeight:1.65,marginBottom:16}}>{p.d}</p>
                  <span style={{fontSize:13,color:PK,fontWeight:600}}>Read more →</span>
                </div>
              </div>
            </FU>
          ))}
        </div>
      </section>
      <section style={{padding:'64px 24px',background:PK,textAlign:'center'}}>
        <FU>
          <h3 style={{fontSize:24,color:'#fff',fontWeight:800,marginBottom:10}}>Want a quick review of your website and lead flow?</h3>
          <p style={{color:'rgba(255,255,255,.85)',marginBottom:28}}>Book a free 15-minute strategy call with Forge Fusion Studios.</p>
          <GBtn white onClick={()=>window.open('https://calendly.com/forgefusionstudios/15min','_blank')}>Book a Free Strategy Call</GBtn>
        </FU>
      </section>
    </div>
  );
};

/* ─── CONTACT PAGE ─────────────────────────────── */
const ContactPage=()=>{
  const[form,setForm]=useState({name:'',company:'',email:'',phone:'',business:'',challenge:'',budget:''});
  const[sent,setSent]=useState(false);
  const upd=(k,v)=>setForm(f=>({...f,[k]:v}));
  const handleSubmit=()=>{
    if(!form.name||!form.email)return alert('Please enter your name and email.');
    const body=encodeURIComponent(`Name: ${form.name}\nCompany: ${form.company}\nEmail: ${form.email}\nPhone: ${form.phone}\nBusiness: ${form.business}\nChallenge: ${form.challenge}\nBudget: ${form.budget}`);
    window.location.href=`mailto:forgefusionstudios@gmail.com?subject=New Enquiry from ${encodeURIComponent(form.name)}&body=${body}`;
    setSent(true);
  };
  const inp={width:'100%',padding:'13px 16px',borderRadius:10,border:'1.5px solid rgba(102,45,145,.18)',fontSize:14,color:DK,background:'#fff',outline:'none',transition:'border-color .2s'};
  const lbl={fontSize:11,fontWeight:600,color:MD,letterSpacing:'.8px',marginBottom:7,display:'block',textTransform:'uppercase'};
  const contactItems=[
    {ic:'envelope',l:'Email',           v:'forgefusionstudios@gmail.com'},
    {ic:'phone2',  l:'Phone / WhatsApp',v:'+92 337 4671221'},
    {ic:'website', l:'Website',         v:'forgefusionstudios.com'},
    {ic:'pin',     l:'Location',        v:'Lahore, Pakistan — working with clients globally'},
    {ic:'clock',   l:'Response Time',   v:'Within 24 hours on business days'},
  ];
  return(
    <div style={{paddingTop:70}}>
      <Hero eyebrow="Let's Talk" title="Start with a conversation." sub="Tell us about your business and what you're trying to grow. We'll review your situation and come back with a clear recommendation — usually within 24 hours."/>
      <section style={{padding:'80px 24px',background:SF}}>
        <div style={{maxWidth:1100,margin:'0 auto',display:'grid',gridTemplateColumns:'1fr 1.55fr',gap:56,alignItems:'start'}} className="grid-2col">
          <FU>
            <h3 style={{fontSize:22,fontWeight:800,color:DK,marginBottom:8}}>Get in touch</h3>
            <p style={{fontSize:14,color:MD,lineHeight:1.78,marginBottom:28}}>Fill out the form and Mustafa will personally review your situation before responding. No templates, no junior staff, no sales scripts.</p>
            {contactItems.map(c=>(
              <div key={c.l} style={{display:'flex',alignItems:'flex-start',gap:14,marginBottom:20}}>
                <div style={{width:40,height:40,borderRadius:'50%',background:GR,display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}>
                  <IC name={c.ic} size={17} color="#fff"/>
                </div>
                <div>
                  <div style={{fontSize:10,fontWeight:600,color:MD,letterSpacing:'1.5px',textTransform:'uppercase',marginBottom:2}}>{c.l}</div>
                  <div style={{fontSize:13,fontWeight:500,color:DK}}>{c.v}</div>
                </div>
              </div>
            ))}
            <div style={{marginTop:32,background:GR,borderRadius:20,padding:'26px 24px'}}>
              <h4 style={{fontSize:16,fontWeight:700,color:'#fff',marginBottom:8}}>Prefer to talk now?</h4>
              <p style={{fontSize:13,color:'rgba(255,255,255,.82)',lineHeight:1.7,marginBottom:16}}>Book a free 15-minute strategy call directly. No prep needed — just show up and talk us through your situation.</p>
              <button onClick={()=>window.open('https://calendly.com/forgefusionstudios/15min','_blank')} style={{background:'#fff',color:PU,padding:'11px 22px',borderRadius:50,border:'none',cursor:'pointer',fontSize:13,fontWeight:700}}>Book a Free 15-Minute Call →</button>
            </div>
            <div style={{marginTop:24,padding:'20px',border:'1px solid rgba(102,45,145,.12)',borderRadius:14}}>
              {['All enquiries are handled directly by Mustafa, the founder.','We respond to every message within 24 hours on business days.','There is no obligation when you book a call or fill out the form.'].map((l,i)=>(
                <div key={i} style={{display:'flex',alignItems:'flex-start',gap:8,marginBottom:i<2?10:0,fontSize:12,color:MD}}>
                  <IC name="check" size={13} color={PK}/>{l}
                </div>
              ))}
            </div>
          </FU>
          <FU d={.14}>
            {sent?(
              <div style={{background:'#fff',borderRadius:24,padding:'56px',textAlign:'center',boxShadow:'0 8px 40px rgba(0,0,0,.06)'}}>
                <div style={{display:'flex',justifyContent:'center',marginBottom:20}}><IB name="checkCircle" size={36} padding={18} radius={50}/></div>
                <h3 style={{fontSize:22,fontWeight:800,color:DK,marginBottom:12}}>Message sent!</h3>
                <p style={{fontSize:15,color:MD,lineHeight:1.78}}>Your email client should have opened with the pre-filled message. We typically respond within 24 hours.</p>
              </div>
            ):(
              <div style={{background:'#fff',borderRadius:24,padding:'40px',boxShadow:'0 8px 40px rgba(0,0,0,.06)'}}>
                <div className="grid-2col" style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:16,marginBottom:16}}>
                  {[
                    {k:'name',   l:'Your Name',             ph:'e.g. Dr. Sarah Ahmed'},
                    {k:'company',l:'Business Name',          ph:'e.g. SureClaims Medical Billing'},
                    {k:'email',  l:'Email Address',          ph:'your@businessemail.com'},
                    {k:'phone',  l:'Phone / WhatsApp (optional)',ph:'+92 or international'},
                  ].map(f=>(
                    <div key={f.k}>
                      <label style={lbl}>{f.l}</label>
                      <input value={form[f.k]} onChange={e=>upd(f.k,e.target.value)} placeholder={f.ph} style={inp}
                        onFocus={e=>e.target.style.borderColor=PK} onBlur={e=>e.target.style.borderColor='rgba(102,45,145,.18)'}/>
                    </div>
                  ))}
                </div>
                <div style={{marginBottom:16}}>
                  <label style={lbl}>What does your business do?</label>
                  <textarea value={form.business} onChange={e=>upd('business',e.target.value)} placeholder="e.g. We are a medical billing company based in Karachi serving private clinics across Pakistan" style={{...inp,height:78,resize:'vertical'}}
                    onFocus={e=>e.target.style.borderColor=PK} onBlur={e=>e.target.style.borderColor='rgba(102,45,145,.18)'}/>
                </div>
                <div style={{marginBottom:16}}>
                  <label style={lbl}>What's your biggest marketing challenge right now?</label>
                  <textarea value={form.challenge} onChange={e=>upd('challenge',e.target.value)} placeholder="e.g. Our website gets traffic but no enquiries / We don't have a consistent content strategy / We need more leads" style={{...inp,height:88,resize:'vertical'}}
                    onFocus={e=>e.target.style.borderColor=PK} onBlur={e=>e.target.style.borderColor='rgba(102,45,145,.18)'}/>
                </div>
                <div style={{marginBottom:28}}>
                  <label style={lbl}>Approximate monthly budget for growth</label>
                  <select value={form.budget} onChange={e=>upd('budget',e.target.value)} style={{...inp,cursor:'pointer'}}>
                    <option value="">Select a range...</option>
                    {['Under PKR 25,000','PKR 25,000–75,000','PKR 75,000–150,000','PKR 150,000+','Not sure yet'].map(o=><option key={o}>{o}</option>)}
                  </select>
                </div>
                <button onClick={handleSubmit} style={{width:'100%',background:GR,color:'#fff',padding:'16px',borderRadius:50,border:'none',cursor:'pointer',fontSize:15,fontWeight:700,letterSpacing:'.5px'}}
                  onMouseEnter={e=>e.target.style.opacity='.9'} onMouseLeave={e=>e.target.style.opacity='1'}>
                  Send Message — We'll respond within 24 hours →
                </button>
                <p style={{fontSize:12,color:MD,textAlign:'center',marginTop:12}}>Or <button onClick={()=>window.open('https://calendly.com/forgefusionstudios/15min','_blank')} style={{background:'none',border:'none',cursor:'pointer',color:PK,fontWeight:600,fontSize:12}}>book a free call directly →</button></p>
              </div>
            )}
          </FU>
        </div>
      </section>
    </div>
  );
};

/* ─── APP ROOT ─────────────────────────────────── */
export default function App(){
  const[page,setPage]=useState('Home');
  const go=p=>{setPage(p);window.scrollTo({top:0,behavior:'smooth'});};
  const pages={
    Home:     <HomePage go={go}/>,
    Services: <ServicesPage go={go}/>,
    Work:     <WorkPage go={go}/>,
    Process:  <ProcessPage go={go}/>,
    Packages: <PackagesPage go={go}/>,
    About:    <AboutPage go={go}/>,
    Blog:     <BlogPage go={go}/>,
    Contact:  <ContactPage go={go}/>,
  };
  return(<><style>{CSS}</style><Nav page={page} go={go}/><main>{pages[page]}</main><Footer go={go}/></>);
}
